// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // owner starts at address(0); only address(0) can pass onlyOwner initially
        vm.prank(address(0));
        c.transferOwnership(actor);
        vm.prank(actor);
        c.owned();
        // Rule: calling owned() must not change the owner.
        assertTrue(c.owner() == actor);
    }
}
